svg.script:
//
(function () {
  var svg = document.getElementById('mass-sc');
  if (!svg) return;

  var iT = svg.querySelector('#sc-it');
  var iD = svg.querySelector('#sc-id');

  function reset() {
    svg.querySelectorAll('.sc-pt-grp.lit').forEach(function(g){ g.classList.remove('lit'); });
    svg.querySelector('#sc-fit').classList.remove('lit');
    if (iT) iT.textContent = '';
    if (iD) iD.textContent = 'Hover a data point or fit line to see details';
  }

  function info(t, d) {
    if (iT) iT.textContent = t;
    if (iD) iD.textContent = d;
  }

  // Data-point groups
  svg.querySelectorAll('.sc-pt-grp').forEach(function(grp) {
    var t = grp.dataset.title || '';
    var d = grp.dataset.desc  || '';
    function on() { reset(); grp.classList.add('lit'); info(t, d); }
    grp.addEventListener('mouseenter', on);
    grp.addEventListener('click',      on);
    grp.addEventListener('mouseleave', reset);
  });

  // Fit line hit target
  var fitHit = svg.querySelector('#sc-fit-hit');
  var fitLine = svg.querySelector('#sc-fit');
  if (fitHit && fitLine) {
    function fitOn() {
      reset();
      fitLine.classList.add('lit');
      info('Best-fit Line', 'y = −2.03 + 1.04·True_Mass  |  R² = 0.9971  |  RMSE ≈ 1.5 g  (n = 6 masses)');
    }
    fitHit.addEventListener('mouseenter', fitOn);
    fitHit.addEventListener('click',      fitOn);
    fitHit.addEventListener('mouseleave', reset);
  }

  svg.addEventListener('click', function(e){
    if (!e.target.closest('.sc-pt-grp') && e.target !== fitHit) reset();
  });

  // ── Build-up: fit line draws on, then data points appear ──
  if (window.matchMedia('(prefers-reduced-motion:reduce)').matches) {
    if (fitLine) fitLine.classList.add('ready');
    svg.querySelectorAll('.sc-pt-grp').forEach(function(g){ g.classList.add('ready'); });
    return;
  }

  // Fit line: stroke-dashoffset draw-on at t=800ms
  setTimeout(function() {
    if (!fitLine) return;
    var len = fitLine.getTotalLength ? fitLine.getTotalLength() : 620;
    fitLine.style.strokeDasharray  = len;
    fitLine.style.strokeDashoffset = len;
    fitLine.classList.add('ready');
    requestAnimationFrame(function(){
      requestAnimationFrame(function(){
        fitLine.style.transition = 'stroke-dashoffset 0.6s cubic-bezier(.4,0,.2,1), opacity .15s';
        fitLine.style.strokeDashoffset = 0;
      });
    });
  }, 800);

  // Data points: staggered reveal starting at t=1500ms
  var pts = svg.querySelectorAll('.sc-pt-grp');
  pts.forEach(function(g, i) {
    setTimeout(function(){
      g.style.transition = 'opacity .25s ease';
      g.classList.add('ready');
    }, 1500 + i * 150);
  });
})();
//
